import React, { useState } from 'react';
import Navbar from './Navbar';
import PropertyList from './PropertyList';
import PropertyForm from './PropertyForm';
import PropertyDetails from './PropertyDetails';
import './App.css';

function App() {
  const [currentPage, setCurrentPage] = useState('propertyList');
  const [selectedPropertyId, setSelectedPropertyId] = useState(null);
  const [isEditMode, setIsEditMode] = useState(false);

  // Navigation handlers
  const navigateTo = (page, propertyId = null, editMode = false) => {
    setCurrentPage(page);
    setSelectedPropertyId(propertyId);
    setIsEditMode(editMode);
  };

  // Render the appropriate component based on current page
  const renderContent = () => {
    switch (currentPage) {
      case 'propertyList':
        return <PropertyList onNavigate={navigateTo} />;
      case 'propertyDetails':
        return <PropertyDetails id={selectedPropertyId} onNavigate={navigateTo} />;
      case 'propertyForm':
        return <PropertyForm id={isEditMode ? selectedPropertyId : null} onNavigate={navigateTo} />;
      default:
        return <PropertyList onNavigate={navigateTo} />;
    }
  };

  return (
    <div className="App">
      <Navbar onNavigate={navigateTo} />
      <div className="container mx-auto p-4">
        {renderContent()}
      </div>
    </div>
  );
}

export default App;
